function copyText(){return copyTranslationText[locale]||copyTranslationText.en}
async function copyMessageForTranslation(text){try{await navigator.clipboard.writeText(text);toast(copyText().copied)}catch{const area=document.createElement("textarea");area.value=text;area.className="clipboard-fallback";document.body.append(area);area.select();const copied=document.execCommand("copy");area.remove();toast(copied?copyText().copied:copyText().failed)}}
function updateCulturalLabels(){const c=cultureText(),s=safetyText(),values={culturalProfileTitle:c.title,culturalProfileIntro:c.intro,namePronunciationLabel:c.pronunciation,preferredContactTimeLabel:c.contactTime,comfortableTopicsLabel:c.topics,culturalContextLabel:c.context,blockedTitle:s.blocked,blockedIntro:s.blockedIntro};Object.entries(values).forEach(([id,value])=>{const el=$("#"+id);if(el)el.textContent=value});const pronunciation=$("#namePronunciation"),topics=$("#comfortableTopics"),context=$("#culturalContext");if(pronunciation)pronunciation.placeholder=c.pronunciationPlaceholder;if(topics)topics.placeholder=c.topicsPlaceholder;if(context)context.placeholder=c.contextPlaceholder;const select=$("#preferredContactTime");if(select)[...select.options].forEach(option=>option.textContent=c[option.value]||option.value);if(state.user&&state.currentPanel==="connections")loadBlockedManagement()}
function applyLanguage(next){locale=translations[next]?next:"en";localStorage.setItem("kindred_app_language",locale);document.documentElement.lang=locale;document.documentElement.dir=locale==="ar"?"rtl":"ltr";$$('[data-i18n]').forEach(el=>el.textContent=tr(el.dataset.i18n));$$('[data-i18n-placeholder]').forEach(el=>el.placeholder=tr(el.dataset.i18nPlaceholder));updateCulturalLabels();$("#languageSelect").value=locale;$("#notificationBell").setAttribute("aria-label",tr("newPeopleNotifications"));if(state.user)$("#authButton").textContent=tr("signOut");renderConnections();renderConversationList()}

function toast(message){const el=$("#toast");el.textContent=message;el.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove("show"),3200)}
function errorMessage(error){console.error(error);const code=error?.code||"";if(code.includes("popup-closed"))return tr("cancelledSignIn");if(code.includes("permission-denied"))return tr("permissionError");if(code.includes("failed-precondition"))return tr("firebaseSetting");return tr("genericError")}
function cleanList(value,max){return [...new Set(value.split(",").map(x=>x.trim()).filter(Boolean))].slice(0,max)}
function pairId(a,b){return [a,b].sort().join("_")}
function escapeText(value){const span=document.createElement("span");span.textContent=value||"";return span.innerHTML}
function availabilityText(value){return tr({"Weekday evenings":"weekdayEvenings","Weekday daytime":"weekdayDaytime","Weekends":"weekends","Flexible":"flexible"}[value]||value)}
function safePhoto(value){const v=String(value||"");return /^https:\/\//i.test(v)||/^data:image\/(?:jpeg|png|webp);base64,/i.test(v)?v:""}
function updatePhotoPreview(value){const img=$("#profilePhotoPreview"),fallback=$("#profilePhotoFallback"),safe=safePhoto(value);if(!img||!fallback)return;img.hidden=!safe;fallback.hidden=!!safe;if(safe)img.src=safe;else img.removeAttribute("src")}
function compressProfilePhoto(file){return new Promise((resolve,reject)=>{if(!["image/jpeg","image/png","image/webp"].includes(file.type))return reject(new Error("photo-invalid"));if(file.size>5*1024*1024)return reject(new Error("photo-too-large"));const reader=new FileReader();reader.onerror=()=>reject(new Error("photo-invalid"));reader.onload=()=>{const image=new Image();image.onerror=()=>reject(new Error("photo-invalid"));image.onload=()=>{const max=360,scale=Math.min(1,max/Math.max(image.width,image.height)),canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext("2d").drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL("image/jpeg",.8))};image.src=reader.result};reader.readAsDataURL(file)})}
async function chooseProfilePhoto(event){const file=event.target.files?.[0];if(!file)return;try{state.pendingPhotoURL=await compressProfilePhoto(file);updatePhotoPreview(state.pendingPhotoURL)}catch(error){event.target.value="";toast(tr(error.message==="photo-too-large"?"photoTooLarge":"photoInvalid"))}}
function showPanel(name){state.currentPanel=name;$$('[data-panel]').forEach(x=>x.hidden=x.dataset.panel!==name);$$('[data-view]').forEach(x=>x.classList.toggle("active",x.dataset.view===name));if(name==="discover"){state.newProfileCount=0;updateNotificationBadge();loadProfiles()}if(name==="connections"){renderConnections();loadBlockedManagement()}if(name==="messages")renderConversationList()}
function requireProfile(){if(state.profile)return true;showPanel("profile");toast(tr("completeProfile"));return false}

async function signIn(){try{await signInWithPopup(auth,provider)}catch(error){toast(errorMessage(error))}}
async function savePrivateUser(user){await setDoc(doc(db,"users",user.uid),{email:user.email||"",displayName:user.displayName||"Member",photoURL:user.photoURL||"",lastLoginAt:serverTimestamp()},{merge:true})}

async function loadOwnProfile(){const snap=await getDoc(doc(db,"profiles",state.user.uid));state.profile=snap.exists()?snap.data():null;const p=state.profile;if(!p){state.pendingPhotoURL=safePhoto(state.user.photoURL||"");$("#timeZone").value=Intl.DateTimeFormat().resolvedOptions().timeZone||"UTC";updatePhotoPreview(state.pendingPhotoURL);return showPanel("profile")}$("#displayName").value=p.displayName||"";$("#profileCity").value=p.city||"";$("#profileCountry").value=p.country||"";$("#bio").value=p.bio||"";$("#interests").value=(p.interests||[]).join(", ");$("#languages").value=(p.languages||[]).join(", ");$("#availability").value=p.availability||"Flexible";$("#friendshipGoal").value=p.friendshipGoal||"close";$("#connectionMode").value=p.connectionMode||"both";$("#contactFrequency").value=p.contactFrequency||"flexible";$("#socialFormat").value=p.socialFormat||"both";$("#communicationStyle").value=p.communicationStyle||"mixed";$("#socialEnergy").value=p.socialEnergy||"balanced";$("#spontaneousInvites").value=p.spontaneousInvites||"sometimes";$("#conversationDepth").value=p.conversationDepth||"both";$("#newCityRole").value=p.newCityRole||"either";$("#timeZone").value=p.timeZone||Intl.DateTimeFormat().resolvedOptions().timeZone||"UTC";$("#intercultural").checked=p.intercultural!==false;$("#namePronunciation").value=p.namePronunciation||"";$("#preferredContactTime").value=p.preferredContactTime||"flexible";$("#comfortableTopics").value=(p.comfortableTopics||[]).join(", ");$("#culturalContext").value=p.culturalContext||"";$("#adultConfirm").checked=p.adultConfirmed===true;$("#activeProfile").checked=p.active!==false;state.pendingPhotoURL=safePhoto(p.photoURL||state.user.photoURL||"");updatePhotoPreview(state.pendingPhotoURL)}

async function saveProfile(event){event.preventDefault();const data={displayName:$("#displayName").value.trim(),city:$("#profileCity").value.trim(),country:$("#profileCountry").value.trim(),bio:$("#bio").value.trim(),interests:cleanList($("#interests").value,12),languages:cleanList($("#languages").value,8),availability:$("#availability").value,friendshipGoal:$("#friendshipGoal").value,connectionMode:$("#connectionMode").value,contactFrequency:$("#contactFrequency").value,socialFormat:$("#socialFormat").value,communicationStyle:$("#communicationStyle").value,socialEnergy:$("#socialEnergy").value,spontaneousInvites:$("#spontaneousInvites").value,conversationDepth:$("#conversationDepth").value,newCityRole:$("#newCityRole").value,timeZone:$("#timeZone").value.trim()||Intl.DateTimeFormat().resolvedOptions().timeZone||"UTC",intercultural:$("#intercultural").checked,namePronunciation:$("#namePronunciation").value.trim(),preferredContactTime:$("#preferredContactTime").value,comfortableTopics:cleanList($("#comfortableTopics").value,10),culturalContext:$("#culturalContext").value.trim(),photoURL:safePhoto(state.pendingPhotoURL||state.profile?.photoURL||state.user.photoURL||""),active:$("#activeProfile").checked,adultConfirmed:$("#adultConfirm").checked,updatedAt:serverTimestamp()};if(!data.adultConfirmed||data.bio.length<30||!data.interests.length||!data.languages.length)return toast(tr("completeFields"));try{await setDoc(doc(db,"profiles",state.user.uid),data);state.profile={...data,updatedAt:new Date()};toast(tr("profileSaved"));showPanel("discover")}catch(error){toast(errorMessage(error))}}

function friendshipCompatibility(p){const mine=state.profile||{},reasons=[];let points=20,possible=20;const pairs=[["friendshipGoal","sameGoal"],["connectionMode","sameConnectionMode"],["contactFrequency","sameRhythm"],["socialFormat","sameSocialFormat"],["communicationStyle","sameCommunicationStyle"],["socialEnergy","sameEnergy"],["spontaneousInvites","sameSpontaneity"],["conversationDepth","sameDepth"]];pairs.forEach(([key,label])=>{if(mine[key]&&p[key]){possible+=8;if(mine[key]===p[key]||mine[key]==="both"||p[key]==="both"||mine[key]==="mixed"||p[key]==="mixed"){points+=8;reasons.push(tr(label))}}});const sharedInterests=(p.interests||[]).filter(x=>(mine.interests||[]).some(y=>y.toLowerCase()===x.toLowerCase())),sharedLanguages=(p.languages||[]).filter(x=>(mine.languages||[]).some(y=>y.toLowerCase()===x.toLowerCase()));possible+=20;if(sharedInterests.length){points+=10;reasons.push(tr("sharedInterestsReason",sharedInterests.slice(0,2).join(", ")))}if(sharedLanguages.length){points+=10;reasons.push(tr("sharedLanguagesReason",sharedLanguages.slice(0,2).join(", ")))}if(mine.timeZone&&p.timeZone){possible+=6;if(mine.timeZone===p.timeZone){points+=6;reasons.push(tr("sameTimeZone"))}}if(mine.intercultural&&p.intercultural){possible+=4;points+=4;reasons.push(tr("bothIntercultural"))}return{score:Math.max(35,Math.min(98,Math.round(points/possible*100))),reasons:reasons.slice(0,3),sharedInterests}}
function profileCard(uid,p){const article=document.createElement("article");article.className="person card";const match=friendshipCompatibility(p),photo=safePhoto(p.photoURL),initial=escapeText((p.displayName||tr("member")).trim().charAt(0).toUpperCase());article.innerHTML=`<div class="person-head">${photo?`<img class="person-avatar" src="${escapeText(photo)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:`<span class="person-avatar person-avatar-fallback" aria-hidden="true">${initial}</span>`}<div><span class="eyebrow">${match.sharedInterests.length?tr("shared",match.sharedInterests.length):tr("newPossibility")}</span><h2>${escapeText(p.displayName)}</h2></div><strong class="match-score">${match.score}%</strong></div><p class="person-meta">${escapeText(p.city)}, ${escapeText(p.country)} · ${escapeText(availabilityText(p.availability))}</p><p>${escapeText(p.bio)}</p><div class="tags">${(p.interests||[]).map(x=>`<span class="tag">${escapeText(x)}</span>`).join("")}</div><p class="match-explanation"><strong>${tr("whyMatch")}</strong> ${escapeText(match.reasons.length?match.reasons.join(" · "):tr("completePassportHint"))}</p><p class="fine">${tr("languagesLabel")}: ${escapeText((p.languages||[]).join(", "))}</p><div class="person-actions"><button class="button connect">${tr("connect")}</button><button class="danger-link report">${tr("reportAction")}</button></div>`;article.querySelector(".connect").onclick=()=>sendRequest(uid,p);article.querySelector(".report").onclick=()=>openReport(uid,p.displayName);return article}

function updateNotificationBadge(){const badge=$("#newProfileCount");if(!badge)return;badge.hidden=state.newProfileCount<1;badge.textContent=state.newProfileCount>99?"99+":String(state.newProfileCount)}
function watchNewProfiles(){state.unsubProfiles?.();state.profileWatchReady=false;state.seenProfileIds=new Set();state.unsubProfiles=onSnapshot(query(collection(db,"profiles"),where("active","==",true),limit(60)),snap=>{const ids=new Set(snap.docs.map(x=>x.id).filter(id=>id!==state.user?.uid));if(!state.profileWatchReady){state.seenProfileIds=ids;state.profileWatchReady=true;return}const added=[...ids].filter(id=>!state.seenProfileIds.has(id));state.seenProfileIds=ids;if(!added.length)return;state.newProfileCount+=added.length;updateNotificationBadge();toast(tr("newMembers",added.length));if(state.currentPanel==="discover")loadProfiles()},error=>toast(errorMessage(error)))}

async function loadBlocked(){const ids=new Set();const [mine,theirs]=await Promise.all([getDocs(query(collection(db,"blocks"),where("blockerId","==",state.user.uid),limit(100))),getDocs(query(collection(db,"blocks"),where("blockedId","==",state.user.uid),limit(100)))]);mine.forEach(x=>ids.add(x.data().blockedId));theirs.forEach(x=>ids.add(x.data().blockerId));return ids}
async function loadBlockedManagement(){const container=$("#blockedPeople");if(!container||!state.user)return;container.innerHTML=`<p class="fine">…</p>`;try{const snap=await getDocs(query(collection(db,"blocks"),where("blockerId","==",state.user.uid),limit(100))),items=await Promise.all(snap.docs.map(async block=>{const uid=block.data().blockedId;if(!state.profiles.has(uid)){const profile=await getDoc(doc(db,"profiles",uid));if(profile.exists())state.profiles.set(uid,profile.data())}return{blockId:block.id,uid}}));container.replaceChildren(...items.map(item=>{const row=document.createElement("article"),button=document.createElement("button");row.className="connection-row";row.innerHTML=`<div><strong>${escapeText(profileName(item.uid))}</strong></div>`;button.className="secondary";button.textContent=safetyText().unblock;button.onclick=()=>unblockPerson(item.blockId);row.append(button);return row}));if(!items.length)container.innerHTML=`<p class="fine">${escapeText(safetyText().noneBlocked)}</p>`}catch(error){container.innerHTML=`<p class="fine">${escapeText(errorMessage(error))}</p>`}}
async function unblockPerson(blockId){try{await deleteDoc(doc(db,"blocks",blockId));toast(safetyText().unblocked);await loadBlockedManagement();await loadProfiles()}catch(error){toast(errorMessage(error))}}
async function loadProfiles(){if(!state.user||!requireProfile())return;const status=$("#discoverStatus"),container=$("#profiles");status.textContent=tr("loadingProfiles");container.replaceChildren();try{const blocked=await loadBlocked();const snap=await getDocs(query(collection(db,"profiles"),where("active","==",true),limit(60)));state.profiles.clear();snap.forEach(x=>state.profiles.set(x.id,x.data()));const mode=$("#filterMode").value,city=$("#filterCity").value.trim().toLowerCase(),nearbyCity=city||(state.profile?.city||"").toLowerCase(),interest=$("#filterInterest").value.trim().toLowerCase();const items=[...state.profiles].filter(([uid,p])=>uid!==state.user.uid&&!blocked.has(uid)&&(mode!=="nearby"||!nearbyCity||(p.city||"").toLowerCase().includes(nearbyCity))&&(mode!=="newcity"||["newcomer","localHelper","either"].includes(p.newCityRole))&&(!interest||(p.interests||[]).some(x=>x.toLowerCase().includes(interest)))).sort((a,b)=>friendshipCompatibility(b[1]).score-friendshipCompatibility(a[1]).score);container.replaceChildren(...items.map(([uid,p])=>profileCard(uid,p)));status.textContent=items.length?tr("profilesFound",items.length):tr("noProfiles")}catch(error){status.textContent=errorMessage(error)}}

async function sendRequest(uid,profile){if(!requireProfile())return;const id=pairId(state.user.uid,uid);try{await setDoc(doc(db,"connections",id),{participants:[state.user.uid,uid].sort(),requestedBy:state.user.uid,recipientId:uid,status:"pending",createdAt:serverTimestamp(),updatedAt:serverTimestamp()});toast(tr("requestSent",profile.displayName))}catch(error){if((error?.code||"").includes("permission-denied"))return toast(tr("requestExists"));toast(errorMessage(error))}}

function profileName(uid){return (uid===state.user?.uid?state.profile:state.profiles.get(uid))?.displayName||tr("member")}
function avatarMarkup(uid,className="chat-avatar"){const profile=uid===state.user?.uid?state.profile:state.profiles.get(uid),photo=safePhoto(profile?.photoURL),name=profile?.displayName||tr("member"),initial=escapeText(name.trim().charAt(0).toUpperCase()||"?");return photo?`<img class="${className}" src="${escapeText(photo)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:`<span class="${className} avatar-fallback" aria-hidden="true">${initial}</span>`}
function otherId(connection){return connection.participants.find(x=>x!==state.user.uid)}
function connectionRow(connection,mode){const other=otherId(connection),row=document.createElement("article");row.className="connection-row";row.innerHTML=`<div><strong>${escapeText(profileName(other))}</strong><div class="fine">${escapeText(connection.status)}</div></div>`;if(mode==="incoming"){const yes=document.createElement("button");yes.className="button";yes.textContent=tr("accept");yes.onclick=()=>answerRequest(connection.id,"accepted");const no=document.createElement("button");no.className="secondary";no.textContent=tr("decline");no.onclick=()=>answerRequest(connection.id,"declined");row.append(yes,no)}if(mode==="accepted"){const msg=document.createElement("button");msg.className="button";msg.textContent=tr("message");msg.onclick=()=>openConversation(connection);const report=document.createElement("button");report.className="danger-link";report.textContent=tr("reportAction");report.onclick=()=>openReport(other,profileName(other));const end=document.createElement("button");end.className="danger-link";end.textContent=safetyText().end;end.onclick=()=>endConnection(connection.id);row.append(msg,report,end)}if(mode==="outgoing"){const cancel=document.createElement("button");cancel.className="danger-link";cancel.textContent=safetyText().cancelRequest;cancel.onclick=()=>endConnection(connection.id);row.append(cancel)}return row}
function renderConnections(){const incoming=$("#incoming"),accepted=$("#accepted"),outgoing=$("#outgoing");if(!incoming||!accepted||!outgoing)return;[incoming,accepted,outgoing].forEach(x=>x.replaceChildren());let incomingCount=0;state.connections.forEach(c=>{if(c.status==="pending"&&c.recipientId===state.user?.uid){incoming.append(connectionRow(c,"incoming"));incomingCount++}else if(c.status==="accepted")accepted.append(connectionRow(c,"accepted"));else if(c.status==="pending")outgoing.append(connectionRow(c,"outgoing"))});$("#requestCount").textContent=incomingCount?`(${incomingCount})`:"";if(!incoming.children.length)incoming.innerHTML=`<p class="fine">${tr("noRequests")}</p>`;if(!accepted.children.length)accepted.innerHTML=`<p class="fine">${tr("noConnections")}</p>`;if(!outgoing.children.length)outgoing.innerHTML=`<p class="fine">${tr("noSent")}</p>`}
async function answerRequest(id,status){try{await updateDoc(doc(db,"connections",id),{status,updatedAt:serverTimestamp()});toast(tr(status==="accepted"?"accepted":"declined"))}catch(error){toast(errorMessage(error))}}
async function endConnection(id){if(!confirm(safetyText().confirmEnd))return;try{await deleteDoc(doc(db,"connections",id));if(state.activeConnectionId===id){state.activeConnectionId=null;state.unsubMessages?.();$("#conversation").innerHTML=`<p>${escapeText(tr("selectConnection"))}</p>`}toast(safetyText().ended)}catch(error){toast(errorMessage(error))}}
function watchConnections(){state.unsubConnections?.();state.unsubConnections=onSnapshot(query(collection(db,"connections"),where("participants","array-contains",state.user.uid)),snap=>{state.connections=snap.docs.map(x=>({id:x.id,...x.data()}));renderConnections();renderConversationList();if(state.currentPanel==="messages"&&state.activeConnectionId){const current=state.connections.find(x=>x.id===state.activeConnectionId);if(current)openConversation(current)}},error=>toast(errorMessage(error)))}

function agreementOption(value,label,current){return `<option value="${value}"${current===value?" selected":""}>${escapeText(tr(label))}</option>`}
function agreementForm(connection){const mine=connection.agreements?.[state.user.uid]||{},other=otherId(connection),theirs=connection.agreements?.[other],ready=Boolean(Object.keys(mine).length&&theirs),fields=[["frequency","contactFrequency",[["daily","daily"],["fewWeekly","fewTimesWeek"],["weekly","weekly"],["flexible","flexible"]]],["meeting","meetingPlan",[["yes","meetYes"],["maybe","meetMaybe"],["onlineOnly","onlineOnly"]]],["format","communicationStyle",[["text","textChat"],["voice","voiceMessages"],["calls","calls"],["mixed","mixed"]]],["closeness","friendshipLevel",[["close","goalClose"],["casual","goalCasual"],["open","openPace"]]],["voice","voiceMessages",[["yes","yes"],["no","no"]]],["spontaneous","spontaneousInvites",[["yes","yes"],["sometimes","sometimes"],["no","no"]]]];const form=`<form id="agreementForm" class="agreement-form">${fields.map(([name,label,options])=>`<label><span>${escapeText(tr(label))}</span><select name="${name}">${options.map(([value,key])=>agreementOption(value,key,mine[name])).join("")}</select></label>`).join("")}<button class="button" type="submit">${escapeText(tr("saveAgreement"))}</button></form>`;if(!ready)return `<section class="agreement-card"><h3>${escapeText(tr("agreementTitle"))}</h3><p>${escapeText(tr("agreementIntro"))}</p>${Object.keys(mine).length?`<p class="agreement-waiting">${escapeText(tr("waitingAgreement"))}</p>`:""}${form}</section>`;const labels={frequency:"contactFrequency",meeting:"meetingPlan",format:"communicationStyle",closeness:"friendshipLevel",voice:"voiceMessages",spontaneous:"spontaneousInvites"},values={daily:"daily",fewWeekly:"fewTimesWeek",weekly:"weekly",flexible:"flexible",yes:"yes",no:"no",maybe:"meetMaybe",onlineOnly:"onlineOnly",text:"textChat",voice:"voiceMessages",calls:"calls",mixed:"mixed",close:"goalClose",casual:"goalCasual",open:"openPace",sometimes:"sometimes"},common=Object.keys(labels).filter(key=>mine[key]===theirs[key]).map(key=>`<li><strong>${escapeText(tr(labels[key]))}:</strong> ${escapeText(tr(values[mine[key]]))}</li>`).join("");return `<section class="agreement-card ready"><h3>${escapeText(tr("commonAgreement"))}</h3>${common?`<ul>${common}</ul>`:`<p>${escapeText(tr("noExactAgreement"))}</p>`}<details><summary>${escapeText(tr("saveAgreement"))}</summary>${form}</details></section>`}
async function saveAgreement(event,connectionId){event.preventDefault();const form=event.currentTarget,data={frequency:form.frequency.value,meeting:form.meeting.value,format:form.format.value,closeness:form.closeness.value,voice:form.voice.value,spontaneous:form.spontaneous.value,updatedAt:new Date().toISOString()},update={updatedAt:serverTimestamp()};update["agreements."+state.user.uid]=data;try{await updateDoc(doc(db,"connections",connectionId),update);toast(tr("agreementSaved"))}catch(error){toast(errorMessage(error))}}
