function journeyText(){return journeyCopy[locale]||journeyCopy.en}
function journeyCard(connection,ready){if(!ready)return "";const copy=journeyText(),other=otherId(connection),mine=connection.journeys?.[state.user.uid]||{steps:[false,false,false,false],continueFriendship:null},theirs=connection.journeys?.[other]||{steps:[false,false,false,false],continueFriendship:null},mySteps=Array.from({length:4},(_,i)=>mine.steps?.[i]===true),theirSteps=Array.from({length:4},(_,i)=>theirs.steps?.[i]===true),count=mySteps.filter(Boolean).length+theirSteps.filter(Boolean).length,growing=mine.continueFriendship===true&&theirs.continueFriendship===true;return `<details class="journey-card"><summary>${escapeText(copy.title)} · ${escapeText(copy.progress(count))}</summary><p>${escapeText(copy.intro)}</p><div class="journey-progress" aria-label="${escapeText(copy.progress(count))}"><span style="width:${count/8*100}%"></span></div><form id="journeyForm"><div class="journey-steps">${copy.steps.map((label,i)=>`<label class="journey-step"><input type="checkbox" name="step${i}"${mySteps[i]?" checked":""}><span>${escapeText(label)}</span><small class="journey-count">${Number(mySteps[i])+Number(theirSteps[i])}/2</small></label>`).join("")}</div><label class="journey-decision"><input type="checkbox" name="continueFriendship"${mine.continueFriendship===true?" checked":""}> <span>${escapeText(copy.continue)}</span></label><button class="secondary" type="submit">${escapeText(copy.save)}</button></form>${growing?`<p class="journey-growing">${escapeText(copy.growing)}</p>`:(mine.continueFriendship===true?`<p class="fine">${escapeText(copy.waiting)}</p>`:"")}</details>`}
async function saveJourney(event,connectionId){event.preventDefault();const form=event.currentTarget,data={steps:[0,1,2,3].map(i=>form[`step${i}`].checked),continueFriendship:form.continueFriendship.checked?true:null,updatedAt:new Date().toISOString()},update={updatedAt:serverTimestamp()};update["journeys."+state.user.uid]=data;try{await updateDoc(doc(db,"connections",connectionId),update);toast(journeyText().saved)}catch(error){toast(errorMessage(error))}}
function renderConversationList(){const list=$("#conversationList");if(!list)return;list.replaceChildren();state.connections.filter(x=>x.status==="accepted").forEach(c=>{const other=otherId(c),b=document.createElement("button");b.className="chat-contact";b.innerHTML=`${avatarMarkup(other,"contact-avatar")}<span class="contact-name">${escapeText(profileName(other))}</span>`;b.onclick=()=>openConversation(c);list.append(b)});if(!list.children.length)list.innerHTML=`<p class="fine">${tr("acceptBefore")}</p>`}
function openConversation(connection){showPanel("messages");state.activeConnectionId=connection.id;const other=otherId(connection),panel=$("#conversation"),agreements=connection.agreements||{},ready=Boolean(agreements[state.user.uid]&&agreements[other]);panel.innerHTML=`<header class="conversation-head">${avatarMarkup(other,"conversation-avatar")}<div><h2>${escapeText(profileName(other))}</h2><span class="chat-status">●</span></div></header>${agreementForm(connection)}<p class="chat-locked"${ready?" hidden":""}>${escapeText(tr("chatLocked"))}</p><div id="messageStream" class="messages" aria-live="polite"${ready?"":" hidden"}></div><form id="messageForm" class="message-form"${ready?"":" hidden"}><div class="emoji-picker" role="group" aria-label="${escapeText(tr("emojiPicker"))}">${["😀","😊","😂","😍","🥰","😎","🤗","🤔","😢","😮","👍","👏","🙏","💪","👋","❤️","💛","🎉","☕","🌍"].map(emoji=>`<button type="button" class="emoji-button" data-emoji="${emoji}" aria-label="${emoji}">${emoji}</button>`).join("")}</div><input id="messageText" maxlength="2000" aria-label="${escapeText(tr("message"))}" required><button class="button">${escapeText(tr("send"))}</button></form>`;$("#agreementForm").onsubmit=event=>saveAgreement(event,connection.id);state.unsubMessages?.();state.unsubMessages=onSnapshot(query(collection(db,"connections",connection.id,"messages"),orderBy("createdAt","asc"),limit(100)),snap=>{const stream=$("#messageStream");stream.replaceChildren();snap.forEach(x=>{const d=x.data(),mine=d.senderId===state.user.uid,row=document.createElement("div"),bubble=document.createElement("div"),p=document.createElement("p");row.className="message-row"+(mine?" mine":"");bubble.className="message-bubble";p.className="message";p.textContent=d.text;row.innerHTML=avatarMarkup(d.senderId,"message-avatar");bubble.append(p);if(!mine){const copy=document.createElement("button");copy.type="button";copy.className="copy-translation";copy.textContent=copyText().button;copy.onclick=()=>copyMessageForTranslation(d.text);bubble.append(copy)}row.append(bubble);stream.append(row)});stream.scrollTop=stream.scrollHeight},error=>toast(errorMessage(error)));$$(".emoji-button").forEach(button=>button.addEventListener("click",()=>{const input=$("#messageText"),emoji=button.dataset.emoji,start=input.selectionStart??input.value.length,end=input.selectionEnd??start;input.value=input.value.slice(0,start)+emoji+input.value.slice(end);input.focus();input.setSelectionRange(start+emoji.length,start+emoji.length)}));$("#messageForm").onsubmit=async event=>{event.preventDefault();if(!ready)return toast(tr("chatLocked"));const input=$("#messageText"),text=input.value.trim(),now=Date.now();if(!text)return;if(now-state.lastMessageAt<3000)return toast(safetyText().slowDown);try{state.lastMessageAt=now;await addDoc(collection(db,"connections",connection.id,"messages"),{senderId:state.user.uid,text,createdAt:serverTimestamp()});input.value=""}catch(error){state.lastMessageAt=0;toast(errorMessage(error))}}}

const openConversationWithoutJourney=openConversation;
function localTimeDetails(timeZone){try{const parts=new Intl.DateTimeFormat(locale,{timeZone,hour:"2-digit",minute:"2-digit",hourCycle:"h23"}).formatToParts(new Date()),hour=Number(parts.find(x=>x.type==="hour")?.value),time=parts.filter(x=>["hour","minute","literal","dayPeriod"].includes(x.type)).map(x=>x.value).join("");return{time,hour,isNight:hour<7||hour>=22}}catch{return{time:"—",hour:null,isNight:false}}}
function culturalBridgeCard(uid){const profile=state.profiles.get(uid)||{},copy=cultureText(),clock=localTimeDetails(profile.timeZone||"UTC"),hasDetails=profile.namePronunciation||profile.culturalContext||(profile.comfortableTopics||[]).length||profile.preferredContactTime;const rows=[];if(profile.namePronunciation)rows.push(`<li><strong>${escapeText(copy.pronunciation)}:</strong> ${escapeText(profile.namePronunciation)}</li>`);if(profile.preferredContactTime)rows.push(`<li><strong>${escapeText(copy.contactTime)}:</strong> ${escapeText(copy[profile.preferredContactTime]||profile.preferredContactTime)}</li>`);if((profile.comfortableTopics||[]).length)rows.push(`<li><strong>${escapeText(copy.topics)}:</strong> ${escapeText(profile.comfortableTopics.join(", "))}</li>`);if(profile.culturalContext)rows.push(`<li><strong>${escapeText(copy.context)}:</strong> ${escapeText(profile.culturalContext)}</li>`);return `<details class="cultural-card"><summary>🌍 ${escapeText(copy.title)} · ${escapeText(copy.localTime)} ${escapeText(clock.time)}</summary>${clock.isNight?`<p class="cultural-night">🌙 ${escapeText(copy.night)}</p>`:""}${hasDetails?`<ul>${rows.join("")}</ul>`:`<p class="fine">${escapeText(copy.notShared)}</p>`}<p class="cultural-tip">${escapeText(copy.tip)}</p></details>`}
openConversation=function(connection){openConversationWithoutJourney(connection);const other=otherId(connection),agreements=connection.agreements||{},ready=Boolean(agreements[state.user.uid]&&agreements[other]);if(!ready)return;const locked=$(".chat-locked"),cultureHolder=document.createElement("div"),journeyHolder=document.createElement("div");cultureHolder.innerHTML=culturalBridgeCard(other);journeyHolder.innerHTML=journeyCard(connection,true);locked.before(cultureHolder.firstElementChild,journeyHolder.firstElementChild);$("#journeyForm").onsubmit=event=>saveJourney(event,connection.id)};

function openReport(uid,name){state.reportTarget=uid;$("#reportTarget").textContent=tr("reportIntro",name);$("#reportDialog").showModal()}
async function submitReport(event){if(event.submitter?.value==="cancel")return;event.preventDefault();const details=$("#reportDetails").value.trim(),reason=$("#reportReason").value;if(!reason||details.length<20)return toast(tr("reportValidation"));try{await addDoc(collection(db,"reports"),{reporterId:state.user.uid,reportedId:state.reportTarget,reason,details,status:"open",createdAt:serverTimestamp()});if($("#alsoBlock").checked){await setDoc(doc(db,"blocks",`${state.user.uid}_${state.reportTarget}`),{blockerId:state.user.uid,blockedId:state.reportTarget,createdAt:serverTimestamp()});await deleteDoc(doc(db,"connections",pairId(state.user.uid,state.reportTarget)))}$("#reportDialog").close();event.target.reset();toast(tr("reportSubmitted"));loadProfiles();if(state.currentPanel==="connections")loadBlockedManagement()}catch(error){toast(errorMessage(error))}}

