onAuthStateChanged(auth,async user=>{state.user=user;$("#signedOut").hidden=!!user;$("#signedIn").hidden=!user;$("#notificationBell").hidden=!user;$("#authButton").textContent=user?tr("signOut"):tr("signIn");state.unsubMessages?.();state.unsubConnections?.();state.unsubProfiles?.();if(!user){state.profile=null;state.pendingPhotoURL="";state.profileWatchReady=false;state.seenProfileIds=new Set();state.newProfileCount=0;updateNotificationBadge();updatePhotoPreview("");return}try{await savePrivateUser(user);await loadOwnProfile();watchConnections();watchNewProfiles();await loadProfiles()}catch(error){toast(errorMessage(error))}});
